const WINDOW_DAYS = 30;
const items = $input.all();
const now = new Date();
const windowStart = new Date(now.getTime() - WINDOW_DAYS * 24 * 60 * 60 * 1000);
let newLeads = 0;
let hotOrUrgentLeads = 0;
for (const item of items) {
  const lead = item.json;
  const createdRaw = (lead['Date Created'] || '').toString().trim();
  if (!createdRaw) continue;
  const created = new Date(createdRaw);
  if (isNaN(created.getTime())) continue;
  if (created >= windowStart && created <= now) {
    newLeads++;
    const temp = (lead['Temperature'] || '').toString().trim();
    const urgency = (lead['Urgency'] || '').toString().trim();
    if (temp === 'Hot' || urgency === 'Emergency') hotOrUrgentLeads++;
  }
}
return [{ json: { metricGroup: 'leads', newLeads: newLeads, hotOrUrgentLeads: hotOrUrgentLeads } }];

const WINDOW_DAYS = 30;
const items = $input.all();
const now = new Date();
const windowStart = new Date(now.getTime() - WINDOW_DAYS * 24 * 60 * 60 * 1000);
let appointmentsBooked = 0;
let appointmentsKept = 0;
for (const item of items) {
  const appt = item.json;
  const apptId = (appt['Appt ID'] || '').toString().trim();
  const idMatch = apptId.match(/^APT-(\d{4})(\d{2})(\d{2})(\d{2})(\d{2})(\d{2})$/);
  if (idMatch) {
    const bookedAt = new Date(Date.UTC(
      parseInt(idMatch[1], 10), parseInt(idMatch[2], 10) - 1, parseInt(idMatch[3], 10),
      parseInt(idMatch[4], 10), parseInt(idMatch[5], 10), parseInt(idMatch[6], 10)
    ));
    if (bookedAt >= windowStart && bookedAt <= now) appointmentsBooked++;
  }
  const status = (appt['Status'] || '').toString().trim();
  const dateStr = (appt['Appt Date'] || '').toString().trim();
  const dateMatch = dateStr.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (dateMatch && status !== 'Cancelled') {
    const apptDate = new Date(Date.UTC(parseInt(dateMatch[1], 10), parseInt(dateMatch[2], 10) - 1, parseInt(dateMatch[3], 10)));
    if (apptDate >= windowStart && apptDate <= now) appointmentsKept++;
  }
}
return [{ json: { metricGroup: 'appointments', appointmentsBooked: appointmentsBooked, appointmentsKept: appointmentsKept } }];

const WINDOW_DAYS = 30;
const items = $input.all();
const now = new Date();
const windowStart = new Date(now.getTime() - WINDOW_DAYS * 24 * 60 * 60 * 1000);
let missedCallsRecovered = 0;
for (const item of items) {
  const log = item.json;
  const channel = (log['Channel'] || '').toString().trim();
  const summary = (log['Message Summary'] || '').toString().trim();
  const whenRaw = (log['Date / Time'] || '').toString().trim();
  if (channel !== 'Phone') continue;
  if (!/missed call/i.test(summary)) continue;
  if (!whenRaw) continue;
  const when = new Date(whenRaw);
  if (isNaN(when.getTime())) continue;
  if (when >= windowStart && when <= now) missedCallsRecovered++;
}
return [{ json: { metricGroup: 'recoveries', missedCallsRecovered: missedCallsRecovered } }];

const COMPANY_NAME = "Valfin Tech";
const WINDOW_DAYS = 30;
const items = $input.all();
const byGroup = {};
for (const item of items) {
  const g = item.json && item.json.metricGroup;
  if (g) byGroup[g] = item.json;
}
const leads = byGroup.leads || { newLeads: 0, hotOrUrgentLeads: 0 };
const appts = byGroup.appointments || { appointmentsBooked: 0, appointmentsKept: 0 };
const recoveries = byGroup.recoveries || { missedCallsRecovered: 0 };
const lines = [];
lines.push('Your Valfin System -- Last ' + WINDOW_DAYS + ' Days for ' + COMPANY_NAME);
lines.push('');
lines.push('New leads captured: ' + leads.newLeads);
if (leads.hotOrUrgentLeads > 0) {
  lines.push('  -> ' + leads.hotOrUrgentLeads + ' flagged Hot/urgent and texted to you the moment they came in');
}
lines.push('Missed calls recovered with an instant text-back: ' + recoveries.missedCallsRecovered);
lines.push('Appointments booked: ' + appts.appointmentsBooked);
lines.push('Appointments kept (not cancelled): ' + appts.appointmentsKept);
lines.push('');
let closing = 'That is ' + appts.appointmentsBooked + ' potential job(s) this system helped put on your calendar';
if (recoveries.missedCallsRecovered > 0) {
  closing += ', including ' + recoveries.missedCallsRecovered + ' that started as a missed call your business would not have otherwise followed up on.';
} else {
  closing += '.';
}
lines.push(closing);
lines.push('');
lines.push('Want the math behind any of these numbers, or to talk about what is next? Just reply -- happy to walk through it.');
const message = lines.join('\n');
return [{ json: {
  reportWindowDays: WINDOW_DAYS,
  newLeads: leads.newLeads,
  hotOrUrgentLeads: leads.hotOrUrgentLeads,
  missedCallsRecovered: recoveries.missedCallsRecovered,
  appointmentsBooked: appts.appointmentsBooked,
  appointmentsKept: appts.appointmentsKept,
  reportMessage: message
} }];
